async function hashPassword(pwd,salt){let enc=new TextEncoder();let data=enc.encode(salt+pwd);let buf=await crypto.subtle.digest('SHA-256',data);return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');}
function genSalt(){return Math.random().toString(36).substring(2,10)+Date.now().toString(36);}
